fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(3);
    let px: i32 = host::display::pointer_x();
    let mut page: i32 = host::display::state_get(0);
    if down == 1 && prev == 0 {
        host::display::state_set(1, px);
    }
    if down == 0 && prev == 1 {
        let dx: i32 = px - host::display::state_get(1);
        if dx < -40 && page < 2 { page = page + 1; }
        if dx > 40 && page > 0 { page = page - 1; }
        host::display::state_set(0, page);
    }
    host::display::state_set(3, down);
    if page == 0 { host::display::clear(0x102030); }
    if page == 1 { host::display::clear(0x103018); }
    if page == 2 { host::display::clear(0x301818); }
    host::display::draw_string(w / 2 - 40, 60, "PAGE", 0xffffff, 2);
    host::display::draw_number(w / 2 + 24, 60, page + 1, 0xffffff, 2);
    host::display::draw_string(w / 2 - 90, h / 2, "SWIPE LEFT OR RIGHT", 0x808080, 1);
    let mut i: i32 = 0;
    while i < 3 {
        let mut c: i32 = 0x404040;
        if i == page { c = 0xffffff; }
        host::display::fill_rect(w / 2 - 30 + i * 24, h - 40, 12, 12, c);
        i = i + 1;
    }
    host::display::present();
}
